INSERT INTO `#__methodology_topics` (`slug`, `kind`, `status`, `title`, `tagline`, `short_description`, `description`, `author_slug`, `reviewer_slug`, `version`, `last_updated`, `tmpl`, `schema_type`, `external_url`, `sort_order`) VALUES ('decision-engine', 'methodology', 'live', 'How the Interactive Decision Notes Verdict Works', 'Every bonus page can answer one question the terms never answer on their own: is this offer sensible for you? The questions, the rule table, the thresholds, and the things the engine refuses to do.', 'The verdict engine behind the per-profile bonus band: three questions max, seven published rules, thresholds calibrated on 2,180 active bonuses, and a profile that never leaves the browser.', 'Methodology behind the Interactive Decision Notes verdict engine on FreeExtraChips bonus pages: profile questions, rule table v1.0 with calibrated turnover thresholds, verified cashout cap handling, operator status override, and versioning policy.', 'sabrina-oconnell', 'david-romano', 'v1.0', '2026-08-17', 'decision-engine', NULL, NULL, 35) ON DUPLICATE KEY UPDATE `kind` = VALUES(`kind`), `status` = VALUES(`status`), `tmpl` = VALUES(`tmpl`), `version` = VALUES(`version`), `last_updated` = VALUES(`last_updated`);
